using ModelContextProtocol.Server;
using System.ComponentModel;

var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddMcpServer()
    .WithHttpTransport()
    .WithTools<WeatherTools>()
    .WithResources<ConfigResources>();

var app = builder.Build();

app.MapMcp();

app.Run();

[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool, Description("Gets the current weather for a city.")]
    public static string GetWeather(string city) =>
        $"The weather in {city} is 72°F and sunny.";
}

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "AppSettings",
        Description = "Returns the application configuration data.",
        MimeType = "application/json")]
    public static string GetAppSettings() =>
        """
        {
          "appName": "McpHttpServer",
          "version": "1.0.0",
          "features": {
            "darkMode": true,
            "maxRetries": 3
          }
        }
        """;
}

